export class PreviewSurface {
  private channel: ExportChannel;
  private banner: string = '';
  async submit(): Promise<void> {
    const outcome = await this.channel.transfer('preview');
    if (typeof outcome === 'boolean') {
      this.banner = 'Completed';
    } else {
      this.banner = 'Unable to export: ' + outcome;
    }
  }
}

export class ExportChannel {
  async transfer(payload: string): Promise<boolean | string> {
    try {
      await socket.send(payload);
      return true;
    } catch (problem) {
      return String(problem);
    }
  }
}

